UPDATE lessons SET title='Year 3, Week 4, Lesson 4: Handwriting speed and legibility', data=json_patch(data,'{"child_mission":"Write legibly at a comfortable pace, then improve unclear letters without rushing.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Keep the independent response and two written check responses; record oral retelling or performance where required by the task.","explicit_teaching":null,"extension":"Create a new example using a completely different character or setting, show the same skill, then explain to another person how you checked its accuracy.","follow_up_challenges":null,"guided_practice":"WE DO — attempt each prompt before comparing to the feedback.\n1. Copy \"The small kite floated above the oval\" slowly and check two letter pairs.\nCOMPARE: c/e and a/o should stay distinct; word spaces should not collapse.\n2. Rewrite \"quick\" and \"chair\" focusing on q, k, c and h.\nCOMPARE: Each letter should be recognisable without guessing from context alone.\n3. Write the kite sentence twice: once slowly, once at a comfortable pace.\nCOMPARE: Both should keep a readable baseline; faster is not better if letters merge.\n4. Identify two unclear words in your faster copy and rewrite them.\nCOMPARE: The rewrite should be clearer, not simply larger and messier.","hoard_words":null,"independent_task":"YOU DO — complete the following substantial original task, not a copied model.\nCopy a 35–50 word original paragraph (from a book or this lesson) twice. Record approximate time for the comfortable copy, circle unclear letters, rewrite two words more clearly, and note one way you kept your hand comfortable.","interactive_activities":null,"learning_area":"English","learning_intention":"Write legibly at a comfortable pace, then improve unclear letters without rushing.","lesson_number":4,"lesson_role":"Speaking and handwriting","materials":["Paper or typing area","Pencil for optional evidence"],"offline_alternative":"Use paper to copy only the original independent prompt; have the child respond in writing or orally as required. Save a photograph or brief parent observation for the learning record.","outcome_codes":["EN2-HANDW-01"],"parent_notes":"Parent: Marking guidance for the independent task: Copy a 35–50 word original paragraph (from a book or this lesson) twice. Record approximate time for the comfortable copy, circle unclear letters, rewrite two words more clearly, and note one way you kept your hand comfo Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using legibility on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Pressing harder does not make letters clearer if shapes become crushed.. Correction: c/e and a/o should stay distinct;. Why it helps the audience is stated.\n\nParent: Likely misconception: Pressing harder does not make letters clearer if shapes become crushed. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating legibility on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with legibility, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about legibility with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for legibility. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":3,"explanation":"This matches the taught method for legibility. The other choices miss a key step or use a common mistake.","options":["Pressing harder does not make letters clearer if shapes become crushed.","A claim that names no evidence from the lesson material.","A method that skips the key step taught in this lesson.","c/e and a/o should stay distinct;"],"question":"Rewrite \"quick\" and \"chair\" focusing on q, k, c and h. Which response is most accurate?","type":"multiple_choice"},{"correct_index":0,"explanation":"This is the misconception to avoid for legibility; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Pressing harder does not make letters clearer if shapes become crushed.","Write legibly at a comfortable pace, then improve unclear letters without rushing.","c/e and a/o should stay distinct;","Careful use of spacing and point to the words or events with clear evidence."],"question":"Which statement is a common mistake when working with legibility?","type":"multiple_choice"},{"correct_index":0,"explanation":"Understanding is shown by new evidence and a named spacing and point to the words or events, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Apply legibility to new material and name the spacing and point to the words or events used.","Repeat the worked example wording with no new evidence.","Pressing harder does not make letters clearer if shapes become crushed.","Name spacing and point to the words or events only, without linking it to legibility."],"question":"Which response best applies legibility with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"The skill is shown by quoting or pointing to wording that carries legibility. The other choices miss a key step or use a common mistake.","options":["Say the writing is good without naming any words.","Pressing harder does not make letters clearer if shapes become crushed.","Point to exact words in the sentence that show legibility and say what they do.","Ignore the sentence and invent a more exciting event."],"question":"Read: \"After the blackout, Tess lit a candle and read the crumpled note.\" Which choice best uses legibility from this lesson?","type":"multiple_choice"},{"correct_index":2,"explanation":"The correct statement applies the language skill with textual evidence. The other choices miss a key step or use a common mistake.","options":["Copy a model sentence from another story unchanged.","Name spacing and point to the words or events without linking it to any words in the text.","c/e and a/o should stay distinct;","Pressing harder does not make letters clearer if shapes become crushed."],"question":"Which statement correctly applies the lesson idea about legibility?","type":"multiple_choice"},{"correct_index":1,"explanation":"Start from a specific textual clue, then explain its effect. The other choices miss a key step or use a common mistake.","options":["Lengthen the answer with adjectives while keeping the same idea.","Locate a specific word, phrase or structural clue before deciding.","Guess from the title alone with no textual clue.","Copy a model sentence from another story unchanged."],"question":"In a new text, what should you do first to analyse spacing and point to the words or events?","type":"multiple_choice"},{"correct_index":1,"explanation":"Repair means fixing meaning or evidence, not padding. The other choices miss a key step or use a common mistake.","options":["Delete the evidence that disagreed with your first guess.","Change the inaccurate idea or missing evidence, not only the length.","Add adjectives without fixing the wrong idea.","Make the answer longer while keeping the same mistake."],"question":"Which revision actually improves meaning for legibility?","type":"multiple_choice"},{"correct_index":1,"explanation":"Accurate transfer needs fresh material with an explained language choice. The other choices miss a key step or use a common mistake.","options":["Pressing harder does not make letters clearer if shapes become crushed.","Use a fresh sentence or text and explain one precise choice about legibility.","Retype the worked model as the final answer.","Change fonts and claim the work is new."],"question":"Which response shows accurate use of legibility on fresh material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about legibility with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating legibility on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using legibility on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for legibility. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with legibility, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Pressing harder does not make letters clearer if shapes become crushed.. Correction: c/e and a/o should stay distinct;. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Submit your original independent work and your brief explanation of the key choices you made.","review_status":"unreviewed","seed_key":"s2-eng-y3-w04-l4","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; compare the existing Coming Soon card and official syllabus content points before marking verified.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise legibility.","Read the mission before you start writing or speaking.","Your goal is: Write legibly at a comfortable pace, then improve unclear letters without rushing."],"guided":["Attempt each guided prompt without looking ahead.","Compare your attempt with the supplied specific feedback.","Guided comparison: Each letter should be recognisable without guessing from context alone."],"learn":["Study the first worked demonstration carefully.","Name the exact words or events that make it work.","Demonstration: I write \"We searched beside the creek\" at an even height, leave a finger-space between words, and check that c and e look different."],"quiz":["Read the whole question and eliminate misconceptions.","Prefer the option that quotes or uses actual evidence.","Likely trap: Racing to finish first is not the goal of this lesson."],"submit":["Include your own response and a short reason.","Proofread names, sequence and punctuation before sending.","Success looks like: Write legibly at a comfortable pace, then improve unclear letters without rushing."],"teach0":["Focus on keep letter size and spacing steady.","Hold this teaching point: Readable handwriting keeps letters a similar size and leaves clear spaces between words before speed increases.","Worked comparison: c/e and a/o should stay distinct; word spaces should not collapse."],"teach1":["Focus on shape tricky letters before racing.","Hold this teaching point: Letters that look alike need careful formation. Fix the shape first; then practise a comfortable pace.","Worked comparison: Each letter should be recognisable without guessing from context alone."],"teach2":["Focus on compare slow and comfortable-pace copies.","Hold this teaching point: A second copy at a natural pace should stay readable. If meaning is lost, slow down again.","Worked comparison: Both should keep a readable baseline; faster is not better if letters merge."],"teach3":["Focus on rewrite only the unclear parts.","Hold this teaching point: Choose two unclear words, rewrite them more carefully, and note how you kept your hand comfortable.","Worked comparison: The rewrite should be clearer, not simply larger and messier."],"write":["Use the independent instructions, not the model words.","Give an original response and the reason behind it.","Independent reminder: Copy a 35–50 word original paragraph (from a book or this lesson) twice. Record approximate time for the comfortable copy, circle unclear letters, rewrite two w"]},"subject":"English","success_criteria":["I can use legibility with a specific example from this lesson.","I can identify spacing and point to the words or events that support it.","I can practise pace independently on a new prompt.","I can notice formation needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying legibility independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which choice best applies this lesson idea about legibility with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI write \"We searched beside the creek\" at an even height, leave a finger-space between words, and check that c and e look different.\n\nYOUR SMALL TRY\nCopy \"The small kite floated above the oval\" slowly and check two letter pairs.\n\nCOMPARE AND CORRECT\nc/e and a/o should stay distinct; word spaces should not collapse.","explain":"Readable handwriting keeps letters a similar size and leaves clear spaces between words before speed increases.\n\nReadable handwriting keeps letters a similar size and leaves clear spaces between words before speed increases. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nPressing harder does not make letters clearer if shapes become crushed. Re-read the prompt and correct the misunderstanding before moving on.","title":"Keep letter size and spacing steady","visual":[{"alt":"Even letter height beside clear spaces between handwritten words.","caption":"Shape and spacing come before increasing speed.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Steady size</text><text x=\"28\" y=\"78\">even letter height</text><text x=\"358\" y=\"42\">Clear spaces</text><text x=\"358\" y=\"78\">gap between words</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I read the first example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or events that carry the meaning before you copy a conclusion.","who":"juno"},{"text":"So I should try the small prompt myself, then compare it with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: I write \"We searched beside the creek\" at an even height, leave a finger-space between words, and check that c and e loo Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I read the first example, but I am not sure which detail matters most.\nJuno: Name the exact words or events that carry the meaning before you copy a conclusion.\nPip: So I should try the small prompt myself, then compare it with the feedback.\nJuno: Pause here. Use this model: I write \"We searched beside the creek\" at an even height, leave a finger-space between words, and check that c and e loo Then write your own attempt."}}]},{"check":{"correct_index":1,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Add a made-up event and describe it as a fact.","Use the example and explain the clue or language choice before trying spacing independently.","Ignore the task and choose an unrelated detail.","Copy every sentence exactly without explaining it."],"question":"Which choice best applies this lesson idea about legibility with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI slow down on k and h so the upright and arms stay clear, then rewrite the whole word once.\n\nYOUR SMALL TRY\nRewrite \"quick\" and \"chair\" focusing on q, k, c and h.\n\nCOMPARE AND CORRECT\nEach letter should be recognisable without guessing from context alone.","explain":"Letters that look alike need careful formation. Fix the shape first; then practise a comfortable pace.\n\nLetters that look alike need careful formation. Fix the shape first; then practise a comfortable pace. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nSkipping a confusing letter and speeding on wastes the practice. Re-read the prompt and correct the misunderstanding before moving on.","title":"Shape tricky letters before racing","visual":[{"alt":"Merged unclear letters contrasted with two carefully rewritten words.","caption":"Rewrite only the unclear parts and keep your hand comfortable.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Unclear copy</text><text x=\"28\" y=\"78\">merged letters</text><text x=\"358\" y=\"42\">Rewrite</text><text x=\"358\" y=\"78\">two clearer words</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Ignore the task and choose an unrelated detail.","Copy every sentence exactly without explaining it.","Use the example and explain the clue or language choice before trying pace independently.","Add a made-up event and describe it as a fact."],"question":"Which choice best applies this lesson idea about legibility with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI time a careful copy, then a comfortable second copy of the same sentence, and circle any unclear letters.\n\nYOUR SMALL TRY\nWrite the kite sentence twice: once slowly, once at a comfortable pace.\n\nCOMPARE AND CORRECT\nBoth should keep a readable baseline; faster is not better if letters merge.","explain":"A second copy at a natural pace should stay readable. If meaning is lost, slow down again.\n\nA second copy at a natural pace should stay readable. If meaning is lost, slow down again. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nRacing to finish first is not the goal of this lesson. Re-read the prompt and correct the misunderstanding before moving on.","title":"Compare slow and comfortable-pace copies"},{"check":{"correct_index":1,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Add a made-up event and describe it as a fact.","Use the example and explain the clue or language choice before trying formation independently.","Ignore the task and choose an unrelated detail.","Copy every sentence exactly without explaining it."],"question":"Which choice best applies this lesson idea about legibility with clear evidence?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI circle \"searched\" because the r and c joined oddly, rewrite it, and shake out my hand between lines.\n\nYOUR SMALL TRY\nIdentify two unclear words in your faster copy and rewrite them.\n\nCOMPARE AND CORRECT\nThe rewrite should be clearer, not simply larger and messier.","explain":"Choose two unclear words, rewrite them more carefully, and note how you kept your hand comfortable.\n\nChoose two unclear words, rewrite them more carefully, and note how you kept your hand comfortable. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nRewriting the whole paragraph when only two words are unclear can cause fatigue. Re-read the prompt and correct the misunderstanding before moving on.","title":"Rewrite only the unclear parts"}],"title":"Year 3, Week 4, Lesson 4: Handwriting speed and legibility","unit_number":1,"unit_title":"Narrative: story elements and planning","week":4,"week_in_unit":4,"word_challenges":null,"worked_example":"I DO — I write \"We searched beside the creek\" at an even height, leave a finger-space between words, and check that c and e look different.\n\nNow look for the exact evidence in the words or actions. I slow down on k and h so the upright and arms stay clear, then rewrite the whole word once.","worked_visuals":[{"alt":"Even letter height beside clear spaces between handwritten words.","caption":"Shape and spacing come before increasing speed.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Steady size</text><text x=\"28\" y=\"78\">even letter height</text><text x=\"358\" y=\"42\">Clear spaces</text><text x=\"358\" y=\"78\">gap between words</text></g></svg>"},{"alt":"Merged unclear letters contrasted with two carefully rewritten words.","caption":"Rewrite only the unclear parts and keep your hand comfortable.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Unclear copy</text><text x=\"28\" y=\"78\">merged letters</text><text x=\"358\" y=\"42\">Rewrite</text><text x=\"358\" y=\"78\">two clearer words</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w04-l4' AND family_id IS NULL;
